using System;
using System.ComponentModel.DataAnnotations;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

// ① 定义强类型选项类
class SmtpOptions
{
    public const string SectionName = "Smtp";

    [Required(ErrorMessage = "Host 不能为空")]
    public string Host { get; set; } = "localhost";

    [Range(1, 65535, ErrorMessage = "Port 必须在 1-65535")]
    public int Port { get; set; } = 25;

    public bool EnableSsl { get; set; }
}

class Program
{
    static void Main()
    {
        // ② 构建配置（演示手动添加，实际由 WebApplicationBuilder 完成）
        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true)
            .AddEnvironmentVariables()
            .Build();

        // ③ 注册 Options + 验证
        var services = new ServiceCollection();
        services.AddSingleton<IConfiguration>(config);

        services.AddOptions<SmtpOptions>()
            .Bind(config.GetSection(SmtpOptions.SectionName))
            .ValidateDataAnnotations()
            .Validate(o => o.Port != 25 || !o.EnableSsl, "Port 25 不应启用 SSL")
            .ValidateOnStart(); // 启动时验证，配置错误直接抛异常

        // ④ 注册使用方
        services.AddSingleton<SmtpMonitor>();
        var sp = services.BuildServiceProvider();

        // ⑤ 触发启动时验证
        var options = sp.GetRequiredService<IOptions<SmtpOptions>>();
        Console.WriteLine($"Smtp: {options.Value.Host}:{options.Value.Port}");

        // ⑥ 监听配置变化
        var monitor = sp.GetRequiredService<SmtpMonitor>();
        Console.WriteLine("修改 appsettings.json 中 Smtp:Port 后将看到变化通知...");
        Console.ReadLine();
    }
}

class SmtpMonitor : IDisposable
{
    private readonly IDisposable _subscription;

    public SmtpMonitor(IOptionsMonitor<SmtpOptions> monitor)
    {
        // 变化回调
        _subscription = monitor.OnChange((opts, name) =>
        {
            Console.WriteLine($"[OnChange] Smtp 配置更新: {opts.Host}:{opts.Port}");
        });
        Console.WriteLine($"[当前值] {monitor.CurrentValue.Host}:{monitor.CurrentValue.Port}");
    }

    // 必须 Dispose，否则 OnChange 回调永远不会被 GC
    public void Dispose() => _subscription?.Dispose();
}
